// ─── appimage-apprun — add the sandbox hint (build/linux/apprun-sandbox-hint_lib.sh) to an AppImage's AppRun ───
// electron-builder's AppRun is generated by app-builder and cannot be templated, so the release
// script repacks the AppImage: runtime bytes kept as they are, squashfs unpacked, AppRun patched,
// squashfs rebuilt with the same compression (gzip, 128 KiB blocks, root-owned files).
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { elfLength, payloadAt } from './appimage-runtime.mjs';

export const HINT_BEGIN = '# ─── devnet-dvpn: sandbox hint';
const ANCHOR = /^BIN="\$APPDIR\/[^"\n]+"\s*$/m;

/** AppRun text with `snippet` inserted right after the `BIN="$APPDIR/…"` line. Throws if it cannot be placed once. */
export function patchAppRun(text, snippet) {
  if (text.includes(HINT_BEGIN)) throw new Error('AppRun already has the sandbox hint');
  const m = ANCHOR.exec(text);
  if (!m) throw new Error('AppRun has no BIN="$APPDIR/…" line to put the sandbox hint after');
  const at = m.index + m[0].length;
  return `${text.slice(0, at)}\n\n${snippet.trimEnd()}\n${text.slice(at)}`;
}

/** Repack `appimage` in place with the hint in its AppRun. Needs unsquashfs + mksquashfs (squashfs-tools). */
export function addSandboxHint(appimage, snippetFile) {
  const buf = fs.readFileSync(appimage);
  const off = elfLength(buf);
  if (!payloadAt(buf, off)) throw new Error(`${appimage}: no squashfs right after the runtime (offset ${off})`);
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'ddv-apprun-'));
  try {
    const root = path.join(tmp, 'root');
    execFileSync('unsquashfs', ['-q', '-no-progress', '-o', String(off), '-d', root, appimage], { stdio: ['ignore', 'ignore', 'inherit'] });
    const apprun = path.join(root, 'AppRun');
    fs.writeFileSync(apprun, patchAppRun(fs.readFileSync(apprun, 'utf8'), fs.readFileSync(snippetFile, 'utf8')));
    fs.chmodSync(apprun, 0o755);
    const sq = path.join(tmp, 'payload.squashfs');
    execFileSync('mksquashfs', [root, sq, '-comp', 'gzip', '-b', '131072', '-all-root', '-noappend', '-no-progress', '-quiet'], { stdio: ['ignore', 'ignore', 'inherit'] });
    fs.writeFileSync(appimage, Buffer.concat([buf.subarray(0, off), fs.readFileSync(sq)]));
    fs.chmodSync(appimage, 0o755);
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
}
